export function copyDiffSummary(
  _text1: string,
  _text2: string,
  result: DiffResult
): string {
  return `
Diff Summary

Lines Added: ${result.stats.added}
Lines Removed: ${result.stats.removed}
Lines Unchanged: ${result.stats.unchanged}
Similarity: ${result.stats.similarity}%

--- Diff ---
${result.lines
  .map((l) =>
    l.type === "added"
      ? `+ ${l.text}`
      : l.type === "removed"
      ? `- ${l.text}`
      : `  ${l.text}`
  )
  .join("\n")}
`.trim();
}

